from __future__ import print_function

import csv
import glob
import os
import stat
import sys
import tempfile


class MergeError(Exception):
    pass


def fail(message):
    raise MergeError(message)


def read_exports(paths):
    header = None
    id_column = None
    records = {}
    origins = {}

    for path in paths:
        try:
            stream = open(path, 'r', newline='')
        except (IOError, OSError) as exc:
            fail("cannot open {0}: {1}".format(path, exc))

        with stream:
            reader = csv.reader(stream)
            try:
                file_header = next(reader)
            except StopIteration:
                fail("{0}: empty export".format(path))
            except csv.Error as exc:
                fail("{0}: invalid CSV header: {1}".format(path, exc))

            if header is None:
                header = file_header
                if 'transaction_id' not in header:
                    fail("{0}: header has no transaction_id column".format(path))
                id_column = header.index('transaction_id')
            elif file_header != header:
                fail("{0}: header does not match the first export".format(path))

            try:
                for line_number, row in enumerate(reader, 2):
                    if not row:
                        continue
                    if len(row) != len(header):
                        fail("{0}:{1}: expected {2} fields, found {3}".format(
                            path, line_number, len(header), len(row)))
                    raw_id = row[id_column]
                    try:
                        transaction_id = int(raw_id, 10)
                    except ValueError:
                        fail("{0}:{1}: transaction_id {2!r} is not an integer".format(
                            path, line_number, raw_id))

                    data = tuple(row[:id_column] + row[id_column + 1:])
                    if transaction_id in records:
                        previous = records[transaction_id]
                        if previous[0] != data:
                            fail("conflicting duplicate transaction_id {0}: {1}:{2} has {3!r}; {4}:{5} has {6!r}".format(
                                transaction_id,
                                origins[transaction_id][0], origins[transaction_id][1], previous[0],
                                path, line_number, data))
                        continue
                    records[transaction_id] = (data, row)
                    origins[transaction_id] = (path, line_number)
            except csv.Error as exc:
                fail("{0}: invalid CSV: {1}".format(path, exc))

    return header, records


def publish(output, header, records):
    output_dir = os.path.dirname(output)
    fd, temporary = tempfile.mkstemp(prefix='.merged.csv.', dir=output_dir)
    try:
        if os.path.exists(output):
            mode = stat.S_IMODE(os.stat(output).st_mode)
        else:
            mode = 0o644
        os.chmod(temporary, mode)
        with os.fdopen(fd, 'w', newline='') as stream:
            fd = None
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(header)
            for transaction_id in sorted(records):
                writer.writerow(records[transaction_id][1])
            stream.flush()
            os.fsync(stream.fileno())
        os.rename(temporary, output)
        temporary = None
    finally:
        if fd is not None:
            os.close(fd)
        if temporary is not None:
            try:
                os.unlink(temporary)
            except OSError:
                pass


def main():
    base = sys.argv[1]
    paths = sys.argv[2:]
    if not paths:
        paths = sorted(glob.glob(os.path.join(base, 'exports', '*.csv')))
    if not paths:
        fail("no export files supplied and no exports/*.csv files found")
    header, records = read_exports(paths)
    publish(os.path.join(base, 'merged.csv'), header, records)
    print("merged {0} unique transactions from {1} export(s)".format(
        len(records), len(paths)))


try:
    main()
except MergeError as exc:
    print("merge: {0}".format(exc), file=sys.stderr)
    sys.exit(1)
except (IOError, OSError) as exc:
    print("merge: publication failed: {0}".format(exc), file=sys.stderr)
    sys.exit(1)
